import { useMutation, useQueryClient, type UseMutationResult } from '@tanstack/react-query';
import type { Todo } from '../types';

interface TogglePayload {
  id: string;
  completed: boolean;
}

async function patchTodo({ id, completed }: TogglePayload): Promise<Todo> {
  const res = await fetch(`/api/todos/${id}`, {
    method: 'PATCH',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ completed }),
  });
  if (!res.ok) throw new Error(res.statusText);
  return res.json();
}

function ToggleTodoButton({ todo }: { todo: Todo }) {
  const queryClient = useQueryClient();

  const mutation = useMutation({
    mutationFn: () => patchTodo({ id: todo.id, completed: !todo.completed }),

    onMutate: async () => {
      // 1. Cancel outgoing refetches so our optimistic value isn't overwritten
      await queryClient.cancelQueries({ queryKey: ['todos'] });

      // 2. Snapshot the current list so we can roll back
      const previousTodos = queryClient.getQueryData<Todo[]>(['todos']);

      // 3. Apply the optimistic change
      queryClient.setQueryData<Todo[]>(['todos'], (old = []) =>
        old.map((t) =>
          t.id === todo.id ? { ...t, completed: !t.completed } : t
        )
      );

      // 4. Return context for onError rollback
      return { previousTodos };
    },

    onError: (_err, _vars, context) => {
      // 5. Restore snapshot on failure
      if (context?.previousTodos) {
        queryClient.setQueryData(['todos'], context.previousTodos);
      }
    },

    onSettled: () => {
      // 6. Always refetch to confirm server state
      queryClient.invalidateQueries({ queryKey: ['todos'] });
    },
  }) as UseMutationResult<Todo, Error, void, { previousTodos?: Todo[] }>;

  return (
    <label className="toggle-label">
      <input
        type="checkbox"
        checked={todo.completed}
        onChange={() => mutation.mutate()}
        disabled={mutation.isPending}
      />
      {mutation.isPending && <span className="pending-indicator" aria-hidden="true">savingâ€¦</span>}
    </label>
  );
}
